D = []


def add(**kw):
    D.append(kw)


add(id="D01", title="Vowel and Consonant Counter", level="Easy", tech="T3 Strings",
    file="D01_vowel_consonant_counter.py",
    statement="Count the vowels (a, e, i, o, u) and consonants in a line of text. Case does not matter. "
              "Ignore digits, spaces and symbols.",
    io=["read the text after the prompt `Enter text: `", "print `Vowels: V` and `Consonants: C` on two lines"],
    cons=["1 ≤ length ≤ 1000", "the text may contain no letters at all (both counts 0)", "`y` is a consonant"],
    samples=[["Programming 101!"], ["AEIOU xyz"], ["2026!!"]])

add(id="D02", title="Second Highest Score", level="Easy", tech="set + sorted",
    file="D02_second_highest_score.py",
    statement="Print the second highest DISTINCT score. If it does not exist, print `None`.",
    io=["`Enter N: ` then `Enter scores: ` (N integers on one line)", "print `Second highest: X` or `Second highest: None`"],
    cons=["1 ≤ N ≤ 1000", "scores may repeat", "scores may be negative", "all scores may be equal"],
    samples=[["5", "90 85 90 70 85"], ["3", "50 50 50"], ["4", "-5 -2 -9 -2"]])

add(id="D03", title="Longest Warming Streak", level="Easy", tech="T6 Streaks",
    file="D03_longest_warming_streak.py",
    statement="Find the longest run of consecutive days where each day is strictly warmer than the day before. "
              "A single day counts as a streak of 1.",
    io=["`Enter N: ` then `Enter the temperatures: `", "print `Longest streak: L`"],
    cons=["1 ≤ N ≤ 10⁵", "equal temperatures break a streak", "the longest streak may be at the very end"],
    samples=[["7", "20 21 22 19 20 21 23"], ["1", "30"], ["4", "5 5 5 5"]])

add(id="D04", title="Island Counter", level="Medium", tech="T9 BFS flood fill",
    file="D04_island_counter.py",
    statement="A map has land `#` and water `.`. Land cells that touch up, down, left or right belong to the same island "
              "(diagonals do NOT connect). Count the islands.",
    io=["`Enter rows and columns: ` → `R C`; then print `Enter the map:` and read R lines", "print `Islands: K`"],
    cons=["1 ≤ R, C ≤ 100", "the map may be all water (0)", "diagonal land cells are separate islands"],
    samples=[["4 5", "##..#", "#...#", "..#..", "....."], ["2 2", "..", ".."], ["3 3", "#.#", ".#.", "#.#"]])

